const wb = $('🔔 Webhook: Generar Imagen').item.json;
const body = wb.body || wb;

const post_id    = String(body.post_id || '');
const company_id = String(body.company_id || '1');
const platform   = (body.platform || 'instagram').toLowerCase();

const postsRaw = $('📋 Obtener Post G54').item.json;
const postsArr = Array.isArray(postsRaw) ? postsRaw
  : (postsRaw.data || postsRaw.posts || [postsRaw]);

const post = postsArr.find(p => String(p.id) === post_id || String(p.post_id) === post_id);
if (!post) throw new Error(`Post ${post_id} not found (total: ${postsArr.length})`);

// --- Config de canal desde G54 (image_config por plataforma, si ya está configurado) ---
let channelConfig = null;
try {
  const channelsResp = $('🎨 G54: Obtener Config Canal').item.json;
  const channels = channelsResp.data || [];
  const platformMap = { instagram: 'Instagram', facebook: 'Facebook', linkedin: 'LinkedIn' };
  const wanted = platformMap[platform] || 'Instagram';
  const match = channels.find(c => c.platform === wanted && c.image_config);
  if (match) channelConfig = match.image_config;
} catch (e) {
  // Login o lectura de canal falló — seguimos con los defaults de siempre
}

const style     = (channelConfig?.img_estilo || body.style || 'realista').toLowerCase();
const formato   = (channelConfig?.img_formato || '').toLowerCase();
const textoModo = (channelConfig?.img_texto_modo || 'sin_texto').toLowerCase();

// --- Extract post fields ---
const clientIdea = post.idea_cliente || post.client_idea || post.descripcion_imagen || '';
const hook       = post.hook || '';
const tema       = post.tema || '';
const copy       = platform === 'facebook' ? (post.copy_facebook || post.copy_instagram || '')
                 : platform === 'linkedin' ? (post.copy_linkedin || post.copy_instagram || '')
                 : (post.copy_instagram || '');

const hashtagMatches = copy.match(/#[\w]+/g) || [];
const hashtagKeywords = hashtagMatches
  .map(h => h.replace('#', '')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .toLowerCase()
  )
  .join(', ');

const copyNarrative = copy.replace(/#[\w]+/g, '').replace(/\n+/g, ' ').trim().slice(0, 200);

let contentRef;
if (clientIdea.trim()) {
  contentRef = clientIdea.trim();
  if (hashtagKeywords) contentRef += `, ${hashtagKeywords}`;
} else {
  const parts = [];
  if (hook)            parts.push(hook);
  if (tema)            parts.push(tema);
  if (copyNarrative)   parts.push(copyNarrative);
  if (hashtagKeywords) parts.push(hashtagKeywords);
  contentRef = parts.filter(Boolean).join('. ');
}

const cfg = $('⚙️ Config Pollinations').item.json;
const baseUrl  = cfg.POLLINATIONS_BASE_URL;
const model = (body.model || cfg.POLLINATIONS_DEFAULT_MODEL || 'flux').toLowerCase();

const businessAnchor = 'industrial wooden crates and packaging boxes in a Miami warehouse, wood crating company, stacked timber crates, export packaging, lumber and plywood construction';

// --- Style instructions: valores nuevos de G54 (img_estilo) + valores viejos por compatibilidad ---
const styleMap = {
  'realista': 'sharp professional photograph, real-world industrial setting, natural warehouse lighting, high resolution DSLR, photorealistic, 4K, no CGI',
  'humanos': 'professional industrial photography, warehouse environment, workers in hard hats and safety vests, organized loading dock, bright clean facility, people actively working',
  '3d': '3D rendered scene, CGI render, three-dimensional modeled objects, studio lighting, clean render aesthetic, product visualization style',
  'animado': 'clean flat digital illustration, vector art style, bold outlines, vibrant flat colors, professional graphic design, animated look',
  'minimalista': 'minimalist composition, clean background, single centered wooden crate or box, generous negative space, simple elegant layout',
  'artistico': 'artistic creative interpretation, painterly style, expressive brushwork feel, premium editorial look, sophisticated color grading',
  'fotografía': 'sharp professional photograph, real-world industrial setting, natural warehouse lighting, high resolution DSLR, photorealistic, 4K, no CGI',
  'fotografia': 'sharp professional photograph, real-world industrial setting, natural warehouse lighting, high resolution DSLR, photorealistic, 4K, no CGI',
  'ilustración': 'clean flat digital illustration, vector art style, bold outlines, vibrant flat colors, professional graphic design',
  'ilustracion': 'clean flat digital illustration, vector art style, bold outlines, vibrant flat colors, professional graphic design',
  'corporativo': 'professional industrial photography, warehouse environment, workers in hard hats and safety vests, organized loading dock, bright clean facility',
  'vibrante':   'vivid saturated colors, dynamic diagonal composition, bold contrast, energetic visual impact, eye-catching social media style',
  'oscuro':     'dramatic dark moody lighting, deep shadows, premium dark warehouse background, metallic and wood accents, sophisticated industrial aesthetic',
};
const styleInstructions = styleMap[style] || styleMap['realista'];

const platformAesthetic = {
  instagram: 'centered subject, strong focal point filling 60% of frame, bold visual hierarchy, vivid balanced colors, mobile feed optimized',
  facebook:  'rule of thirds layout, subject on left or right third, breathing room on edges, clear horizon line, desktop and mobile feed optimized',
  linkedin:  'clean organized layout, neutral-to-warm color palette, professional industrial tone, clear separation of foreground and background',
};
const platformSpec = platformAesthetic[platform] || platformAesthetic.instagram;

// --- Dimensiones: img_formato de G54 tiene prioridad sobre el default por plataforma ---
const formatoDims = {
  'cuadrada':   { width: 1080, height: 1080, label: 'square 1:1 composition' },
  'vertical':   { width: 1080, height: 1350, label: 'vertical 4:5 composition' },
  'horizontal': { width: 1920, height: 1080, label: 'wide horizontal 16:9 composition' },
};
const platformDefaultDims = {
  instagram: { width: 1080, height: 1080, label: 'square 1:1 composition' },
  facebook:  { width: 1200, height: 630,  label: 'wide 1.91:1 landscape composition' },
  linkedin:  { width: 1200, height: 627,  label: 'wide landscape composition' },
};
const { width, height, label: formatLabel } = formatoDims[formato] || platformDefaultDims[platform] || platformDefaultDims.instagram;

// --- Modo de texto (img_texto_modo de G54) ---
const textoInstructions = {
  'sin_texto': 'absolutely no text, no words, no letters, no typography, no captions rendered in the image',
  'solo_titulo': `include the title "${hook || tema}" as clean bold legible text in the image`,
  'titulo_subtitulo': `include the title "${hook || tema}" as clean bold legible text with a smaller subtitle in the image`,
  'titulo_sub_detalles': `include the title "${hook || tema}" as clean bold legible text with supporting detail text in the image`,
  'libre': 'any text or labels must be clean, sharp, legible and properly rendered',
};
const textQuality = textoInstructions[textoModo] || textoInstructions['sin_texto'];

const negatives = [
  'no business portraits, no headshots, no stock photo people posing, no office environment',
  'no distorted text, no garbled letters, no corrupted fonts, no illegible writing',
  'no extra limbs, no deformed hands, no fused fingers, no broken anatomy',
  'no impossible angles, no floating objects without shadow, no distorted perspective',
  'no muddy textures, no inconsistent lighting direction',
  'no cropped heads, no half-cut subjects, no unintended duplicates',
  'no watermarks, no low resolution, no JPEG artifacts, no noise',
  'never invent, create, fabricate or hallucinate a brand logo or emblem of any kind, no fictional or fake company logos, no made-up brand marks or insignias, absolutely no logo generation under any circumstance',
].join(', ');

const prompt = [
  businessAnchor,
  contentRef.slice(0, 300),
  formatLabel,
  platformSpec,
  styleInstructions,
  textQuality,
  negatives,
].join(', ');

const promptEncoded = encodeURIComponent(prompt.slice(0, 1800));
const imageUrl = `${baseUrl}/${promptEncoded}?model=${model}&width=${width}&height=${height}&nologo=true&seed=${Date.now()}`;

// Token de sesión G54 (login) — necesario para subir la imagen y guardar el post; el AGENT_TOKEN no sirve en estas rutas
let g54AccessToken = '';
try {
  g54AccessToken = $('🔐 G54: Login Sesión').item.json.access_token || '';
} catch (e) {}

return [{ json: {
  post_id,
  company_id,
  platform,
  style,
  formato,
  textoModo,
  model,
  current_status: post.status || 'aprobado',
  client_idea_used: clientIdea ? clientIdea.slice(0, 100) : null,
  hashtags_used: hashtagKeywords.slice(0, 150),
  content_ref: contentRef.slice(0, 200),
  image_url_template: imageUrl,
  g54_access_token: g54AccessToken,
}}];

const inp = $('🎨 Construir Prompt').item.json;
let finalUrl = inp.image_url_template; // fallback: URL externa de Pollinations

try {
  const uploadResult = $('📤 G54: Subir Imagen').item.json;
  if (uploadResult && uploadResult.ok && uploadResult.url) {
    finalUrl = uploadResult.url; // preferido: imagen ya subida al storage de G54
  }
} catch (e) {
  // El nodo de subida no corrió o falló — usar la URL de Pollinations tal cual
}

return [{ json: {
  post_id:          inp.post_id,
  company_id:       inp.company_id,
  image_url:        finalUrl,
  status:           inp.current_status || 'aprobado',
  g54_access_token: inp.g54_access_token,
}}];

